INSERT INTO partidos (equipo_categoria_local_id,equipo_categoria_visita_id,jornada_id,fecha,goles_local,goles_visita,comentario,estado) SELECT ecl.id,ecv.id,j.id,DATE_ADD(DATE_ADD(@fecha_inicio, INTERVAL 0 DAY), INTERVAL 9 HOUR),2,0,'Importado desde Excel; fecha provisional','jugado' FROM equipo_categoria ecl JOIN equipos el ON el.id=ecl.equipo_id JOIN categorias c ON c.id=ecl.categoria_id JOIN equipo_categoria ecv ON ecv.categoria_id=c.id JOIN equipos ev ON ev.id=ecv.equipo_id JOIN jornadas j ON j.nombre='2008-2009 - Jornada 1' WHERE c.nombre='2008-2009' AND UPPER(TRIM(el.nombre))=UPPER(TRIM('COMBINADO AMERICA')) AND UPPER(TRIM(ev.nombre))=UPPER(TRIM('BARCELONA')) AND NOT EXISTS (SELECT 1 FROM partidos p WHERE p.equipo_categoria_local_id=ecl.id AND p.equipo_categoria_visita_id=ecv.id AND p.jornada_id=j.id) LIMIT 1;
INSERT INTO partidos (equipo_categoria_local_id,equipo_categoria_visita_id,jornada_id,fecha,goles_local,goles_visita,comentario,estado) SELECT ecl.id,ecv.id,j.id,DATE_ADD(DATE_ADD(@fecha_inicio, INTERVAL 21 DAY), INTERVAL 9 HOUR),0,2,'Importado desde Excel; fecha provisional','jugado' FROM equipo_categoria ecl JOIN equipos el ON el.id=ecl.equipo_id JOIN categorias c ON c.id=ecl.categoria_id JOIN equipo_categoria ecv ON ecv.categoria_id=c.id JOIN equipos ev ON ev.id=ecv.equipo_id JOIN jornadas j ON j.nombre='2008-2009 - Jornada 4' WHERE c.nombre='2008-2009' AND UPPER(TRIM(el.nombre))=UPPER(TRIM('PILARES MXDI')) AND UPPER(TRIM(ev.nombre))=UPPER(TRIM('COMBINADO AMERICA')) AND NOT EXISTS (SELECT 1 FROM partidos p WHERE p.equipo_categoria_local_id=ecl.id AND p.equipo_categoria_visita_id=ecv.id AND p.jornada_id=j.id) LIMIT 1;
